return $input.all().map((item) => {
  const input = item.json;
  const status = Number(input.httpCode || input.statusCode || input.error?.httpCode || 0);
  const retryable = status === 0 || status === 408 || status === 409 || status === 425 || status === 429 || status >= 500;
  const attempt = Number(input.attempt || 1);
  const delaySeconds = retryable ? Math.min(3600, Math.round(30 * Math.pow(2, Math.max(0, attempt - 1)))) : 0;
  return { json: { ...input, retryDecision: retryable && attempt < 6 ? 'retry' : retryable ? 'quarantine' : 'permanent_failure', retryable, nextAttempt: attempt + 1, delaySeconds } };
});
